/*selectCommonMpIvDlvryChoicePopList*/ SELECT ROWNUM NUM, A.CODE, A.TEXT1, A.TEXT2, A.TEXT3, A.TYPE FROM ICOMCOD2 A WHERE A.TYPE='C012' AND A.FLAG='Y'
AND A.COMPANY_CODE IN ('KRDONG0110','KRDONG0107','KRDONG0128','KRDONG0732')
AND A.COMPANY_CODE = #{st_buyer_code}
ORDER BY A.COMPANY_CODE
